  {"note": "Add the foreign key as NOT VALID: checks every new/updated order from now on without scanning the 10M existing rows. It needs a brief SHARE ROW EXCLUSIVE lock on orders and customers, which blocks inserts while held, so take it with a 200 ms lock_timeout and retry (up to 50 times) instead of queueing behind in-flight inserts and stalling the app. Skipped if the constraint already exists.",
   "sql": "DO $$ DECLARE i int; BEGIN IF EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.orders'::regclass AND conname = 'orders_customer_id_fkey') THEN RETURN; END IF; PERFORM set_config('lock_timeout', '200ms', true); FOR i IN 1..50 LOOP BEGIN ALTER TABLE public.orders ADD CONSTRAINT orders_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES public.customers (id) NOT VALID; RETURN; EXCEPTION WHEN lock_not_available THEN PERFORM pg_sleep(0.5); END; END LOOP; RAISE EXCEPTION 'could not lock orders/customers to add orders_customer_id_fkey after 50 attempts'; END $$;"},
  {"note": "Validate the existing rows. VALIDATE CONSTRAINT holds only SHARE UPDATE EXCLUSIVE on orders and ROW SHARE on customers, so the app keeps reading and inserting during the full scan. No statement timeout (the scan of ~1.3 GB can take a while); lock_timeout so it never waits indefinitely. If an orphaned order exists this fails and the plan stops, leaving the NOT VALID constraint in place (still enforced for new rows).",
   "sql": "SET statement_timeout = 0; SET lock_timeout = '10s'; ALTER TABLE public.orders VALIDATE CONSTRAINT orders_customer_id_fkey;"},
  {"note": "Verify the constraint exists and is validated.",
   "sql": "DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.orders'::regclass AND conname = 'orders_customer_id_fkey' AND contype = 'f' AND convalidated) THEN RAISE EXCEPTION 'orders_customer_id_fkey missing or not validated'; END IF; END $$;"}
]}
